(window.TNQ=window.TNQ||[]).push({"terms":{"지위비행":{"d":"성인이 하면 문제되지 않으나 소년이라는 신분 때문에 비행이 되는 행위로 음주, 흡연, 가출 등이 있다.","r":[]},"일탈행동":{"d":"사회가 기대하는 규범에서 벗어난 행동입니다.","r":["지위비행"]},"비일관성척도":{"d":"비슷한 내용의 문항에 서로 다르게 답하는 정도를 보아 부주의한 응답을 가려내는 타당도 척도입니다.","r":["저빈도척도"]},"저빈도척도":{"d":"대부분 사람이 거의 하지 않는 응답을 얼마나 했는지 보아 성의 없는 응답을 가려내는 척도입니다.","r":["비일관성척도"]},"보호처분":{"d":"소년법에 따라 소년부 판사가 소년의 품행 교정을 위해 내리는 1호부터 10호까지의 처분이다.","r":[]},"소년분류심사원":{"d":"법원 소년부가 위탁한 소년을 수용하고 심리와 행동을 조사하는 기관입니다.","r":["보호처분"]},"재통합적 수치심":{"d":"브레이스웨이트의 개념으로, 행위는 비난하되 행위자는 다시 공동체의 일원으로 받아들이는 수치심이다.","r":[]},"감호교육":{"d":"소년을 보호하고 감독하며 교육하는 것을 뜻하는 소년법의 용어입니다.","r":[]},"보조인":{"d":"소년 사건에서 소년의 이익을 돕기 위해 선정되는 조력자로 변호사 등이 맡습니다.","r":[]},"학교폭력대책심의위원회":{"d":"학교폭력 사안을 심의하고 가해학생에 대한 조치를 정해 요청하는 위원회입니다.","r":[]},"아노미이론":{"d":"머튼이 제시한 이론으로, 문화적 목표와 이를 이룰 제도화된 수단 사이의 괴리에서 일탈이 생긴다고 본다.","r":[]},"사회유대이론":{"d":"허쉬의 이론으로, 애착, 관여, 참여, 신념의 유대가 약해질 때 비행이 나타난다고 본다.","r":[]},"차별접촉이론":{"d":"서덜랜드의 이론으로, 범죄는 친밀한 집단과의 상호작용 속에서 기술, 동기, 합리화를 학습한 결과라고 본다.","r":[]},"사회학습이론":{"d":"에이커스가 제시한 이론으로, 차별접촉, 정의, 차별적 강화, 모방을 통해 비행을 학습한다고 본다.","r":[]},"하위계층문화이론":{"d":"밀러가 주장한 이론으로, 하위계층 고유의 관심의 초점인 말썽부리기, 강인함 등이 비행으로 이어진다고 본다.","r":[]},"우범소년":{"d":"성격이나 환경에 비추어 장래 범죄를 저지를 우려가 있는 소년이다.","r":[]},"사회봉사명령":{"d":"소년법상 보호처분의 하나로, 일정 시간 무보수로 사회에 봉사하게 하는 처분이다.","r":[]},"수강명령":{"d":"소년법상 보호처분의 하나로, 일정 시간 교육이나 강의를 받게 하는 처분이다.","r":[]},"현실치료":{"d":"글래서가 제시한 상담 접근으로, 기본 욕구를 충족하는 책임 있는 선택과 현재 행동의 평가를 강조한다.","r":[]},"회복적 사법":{"d":"처벌보다 비행이 야기한 손상의 회복을 목표로 용서, 보상, 치유, 통합을 강조하는 사법 모델이다.","r":[]},"응보적 사법":{"d":"비행에 대해 강제적 처벌을 부과하는 것을 중심으로 하는 전통적 사법 모델이다.","r":[]},"비범죄화":{"d":"일정한 행위를 형사처벌 대상에서 제외하는 것을 말하며 낙인 방지를 위한 범죄통제 방안의 하나이다.","r":[]},"낙인이론":{"d":"일탈은 행위 자체가 아니라 사회가 붙인 낙인의 결과로 굳어진다고 보는 이론이다.","r":[]},"악의 극화":{"d":"탄넨바움의 개념으로, 비행을 악으로 규정하고 반응하는 과정이 오히려 비행을 강화한다는 것이다.","r":[]},"동기강화상담":{"d":"밀러와 롤닉이 개발한 상담으로, 공감과 불일치감 발달을 통해 내담자의 변화 동기를 끌어낸다.","r":[]},"체계적 둔감법":{"d":"이완 상태에서 불안을 일으키는 자극을 약한 것부터 단계적으로 접하게 해 불안을 줄이는 행동주의 기법이다.","r":[]},"소거":{"d":"강화를 중단하여 이전에 강화되던 행동이 점차 줄어들게 하는 행동주의 기법이다.","r":[]},"사이버 불링":{"d":"인터넷과 모바일 같은 사이버 공간에서 특정인을 반복적으로 괴롭히는 행위이다.","r":[]},"PAI":{"d":"성격평가질문지로, 타당도척도, 임상척도, 치료고려척도, 대인관계척도로 구성된 자기보고형 검사이다.","r":[]},"K-WAIS":{"d":"한국판 웩슬러 성인용 지능검사로, 언어이해, 지각추론 등의 지표와 소검사로 인지 기능을 평가한다.","r":[]},"지각추론":{"d":"웩슬러 지능검사의 지표로, 토막 짜기, 행렬 추리, 퍼즐 등 소검사로 비언어적 추론 능력을 측정한다.","r":[]},"동조형":{"d":"머튼의 적응유형으로, 문화적 목표와 제도화된 수단을 모두 수용하는 방식이다.","r":[]},"혁신형":{"d":"머튼의 적응유형으로, 문화적 목표는 수용하지만 이를 이룰 제도화된 수단은 거부하는 방식이다.","r":[]},"의례형":{"d":"머튼의 적응유형으로, 문화적 목표는 포기하고 제도화된 수단만 따르는 방식이다.","r":[]},"도피형":{"d":"머튼의 적응유형으로, 문화적 목표와 제도화된 수단을 모두 거부하는 방식이다.","r":[]},"청소년쉼터":{"d":"가정 밖 청소년을 일정 기간 보호하면서 상담, 주거, 학업, 자립 등을 지원하는 청소년복지시설이다.","r":[]},"CYS-Net":{"d":"위기청소년을 지원하기 위해 지역사회 청소년통합지원체계로 구축·운영하는 지역 연계망이다.","r":[]},"반사회적 성격장애":{"d":"타인의 권리를 무시하거나 침해하는 행동 양식이 지속되고 죄책감이 결여되는 성격장애이다.","r":[]},"자기통제력":{"d":"갓프레슨과 허쉬의 이론에서 비행의 유일한 원인으로 보며, 어린 시절 부모의 양육으로 형성된다고 한다.","r":[]}},"notes":{"12개월 이내에 세 번 보인다":"신체적 공격이 있는 폭발이 열두 달 안에 세 차례 나타나야 기준에 해당합니다.","13세 이전에 무단결석을 자주 한다":"이른 나이에 시작된 규칙 위반이어서 품행장애의 심각성을 판단하는 단서가 됩니다.","14세 이상의 소년에게만 할 수 있다":"사회봉사명령은 열네 살 미만의 소년에게는 부과할 수 없다는 연령 제한입니다.","365일 24시간 원스톱(one-stop)서비스 제공을 목적으로 한다":"밤낮없이 연중 한곳에서 필요한 지원을 한꺼번에 받을 수 있도록 하는 것이 목적입니다.","4점 평정척도로 반응하도록 함":"응답을 네 단계 가운데 고르게 하여 두 가지 선택지만 있는 방식보다 정도를 세밀하게 나타냅니다.","공격성, 스트레스, 비지지, 치료거부, 자살관념으로 구성되어 있다":"치료 계획에 고려할 위험 요소와 치료 의지를 알려 주는 다섯 개의 척도입니다.","교육장이 학교폭력예방 및 대책에 관한 법률 제17조제1항에 따라 내린 조치에 이의가 있는 가해학생 또는 그 보호자는 행정심판법에 따른 행정심판을 청구할 수 있다":"교육장의 조치에 불복하는 가해 학생과 보호자는 행정심판법에 따라 행정심판으로 다툴 수 있습니다.","구체적인 대상연령은 5 ∼ 15세 이다":"이 프로그램이 겨냥하는 연령 범위가 다섯 살부터 열다섯 살까지라는 정보입니다.","내담자를 훈련시키기 위해 보호자, 교사의 협조를 구한다":"상담실 밖의 일상에서 훈련이 이어지도록 주변 어른들에게 협력을 요청합니다.","내담자에게 구체적이고 행동적인 것을 목표로 한다":"막연한 바람이 아니라 눈에 보이는 행동으로 말할 수 있는 목표를 세웁니다.","내담자에게 없는 것 보다는 있는 것에 관심을 둔다":"부족한 점보다 이미 가진 자원과 잘되는 부분에서 해결의 단서를 찾습니다.","내담자에게 중요한 것을 목표로 한다":"해결중심 상담에서는 상담자가 아닌 내담자가 의미를 두는 것이 목표가 됩니다.","내담자의 작은 강점을 확장시키고 변화의 기반으로 삼는다":"작은 강점이라도 키워 나가는 것을 변화의 출발점으로 삼습니다.","다른 사람의 재산을 고의적으로 파괴한다":"남의 물건이나 재물을 일부러 망가뜨리는 행동도 품행장애 진단 기준에 해당합니다.","당연직 위원의 임기는 그 재임기간으로 한다":"직책 때문에 위원이 된 사람은 그 직위에 있는 동안만 위원으로 일합니다.","무시하거나 신경 쓰지 않는다":"다른 사람이 어떻게 느끼는지에 공감하지 못하고 무관심하게 대합니다.","문제를 해결하기 위해서는 지역사회의 협력을 필요로 한다":"가해자와 피해자만이 아니라 지역사회가 함께 참여해야 회복이 이루어진다고 봅니다.","미리 계획된 것이 아니며, 가시적인 목표를 달성하기 위해 저질러진 행동이 아니다":"돈이나 지위 같은 얻으려는 것이 없이 충동적으로 터지는 공격이라는 점이 특징입니다.","반복적인 행동폭발 동안 표현된 공격성의 정도는 심리사회적 스트레스 요인에 의해 촉발되거나 유발되는 정도를 심하게 넘어선 것이다":"폭발한 공격성이 계기가 된 스트레스에 비해 지나치게 크다는 것이 간헐적 폭발장애의 기준입니다.","범죄로 인한 피해를 회복하는 것을 강조한다":"가해자를 처벌하는 것보다 피해자가 입은 손해와 상처를 회복시키는 데 초점이 있습니다.","법률상 감호교육(監護敎育)을 할 의무가 있는 자 또는 현재 감호하는 자를 말한다":"소년법에서 보호자는 친권자 같은 법적 의무자뿐 아니라 실제로 소년을 돌보는 사람도 포함합니다.","보상, 치유, 통합 등을 강조한다":"처벌 자체보다 피해를 갚고 관계를 치유하며 공동체에 다시 통합시키는 데 가치를 둡니다.","보호처분이 계속 중일 때에 사건 본인에 대하여 유죄판결이 확정된 경우에 보호처분을 한 소년부 판사는 그 처분을 존속할 필요가 없다고 인정하면 결정으로써 보호처분을 취소할 수 있다":"보호처분 중 유죄판결이 확정되면 판사가 처분을 유지할 필요가 없다고 보아 결정으로 취소할 수 있습니다.","본인이 잘못을 저질러도 후회나 죄책감을 느끼지 않는다":"냉담하고 무감각한 특성의 하나로, 잘못을 하고도 미안함을 느끼지 못합니다.","비일관성척도, 저빈도척도, 부정적인상척도, 긍정적인상척도로 구성된다":"이 검사의 타당도 척도는 응답의 성실성과 왜곡 여부를 가리는 네 가지로 이루어집니다.","비행집단 내에서의 행동이 자신의 재능과 에너지를 소모하고 있다는 것을 인식하도록 돕는다":"비행 활동이 자신의 가능성을 낭비하게 한다는 점을 깨닫게 하여 변화 동기를 만듭니다.","비행집단 대신 소속감과 정체감을 제공하는 새로운 지지체계를 형성하도록 돕는다":"비행집단이 주던 소속감을 건전한 모임으로 대신 채우도록 돕는 것입니다.","비행집단의 압력에 대처하는 방법을 알게 한다":"또래 집단이 비행을 부추길 때 거절하고 벗어나는 방법을 가르칩니다.","사회가 청소년에게 기대하는 규범에 벗어난":"청소년에게 기대되는 규범에서 어긋난 행동을 설명하는 문장의 앞부분입니다.","소년부 판사는 검증, 압수 또는 수색을 할 수 있다":"소년 사건에서도 증거를 확보하려고 판사가 검증과 압수와 수색을 할 권한이 있습니다.","소년부 판사는 보호사건 심리결과 12세 이상의 소년에게만 할 수 있다":"수강명령과 장기 소년원 송치는 열두 살 이상의 소년에게만 결정할 수 있습니다.","소년부 판사는 적당하다고 인정하는 자에게 참석을 허가할 수 있다":"소년 심리는 원칙적으로 공개하지 않으나 판사가 적당하다고 인정하는 사람은 참석시킬 수 있습니다.","소년의 품행을 교정하고 피해자를 보호하기 위하여 필요하다고 인정하면 소년에게 피해 변상 등 피해자와의 화해를 권고할 수 있다":"판사는 소년을 바로잡고 피해자를 보호하려고 피해 변상 등 화해를 하도록 권할 수 있습니다.","소년이 소년분류심사원에 위탁된 경우 보조인이 없을 때에는 법원은 변호사 등 적정한 자를 보조인으로 선정하여야 한다":"소년분류심사원에 위탁된 소년에게 조력자가 없다면 법원이 직접 변호사 등을 보조인으로 정해야 합니다.","송치서와 조사관의 조사보고에 따라 사건의 심리를 개시할 수 없거나 개시할 필요가 없다고 인정하면 심리를 개시하지 아니한다는 결정을 하여야 한다":"서류를 보고 심리를 시작할 수 없거나 필요 없다고 판단되면 판사는 심리 불개시 결정을 내려야 합니다.","심리검사 척도개발에서 합리적, 경험적 접근을 강조하며 이에 근거를 두고 개발되었다":"이론과 자료 두 방법을 결합해 척도를 만든 검사라는 설명입니다.","여성가족부령으로 정하는 바에 따라 전담공무원 및 민간 전문인력을 배치할 수 있다":"통합지원을 맡을 담당 공무원과 민간 전문가를 기준에 따라 둘 수 있습니다.","위기문항을 제시하여 그 내용을 수검자에게 질문하고 추가 정보를 수집함":"자살이나 폭력과 관련된 중요 문항을 골라 수검자에게 직접 물어 더 자세한 정보를 얻습니다.","위기청소년을 다각적으로 지원하는 1388 청소년지원단을 구성하여 운영하고 있다":"여러 방면으로 위기 청소년을 돕는 청소년지원단을 꾸려 운영하고 있다는 내용입니다.","위원의 임기는 2년으로 하며, 연임할 수 있다":"위원은 이년간 일하고 한 번 더 맡을 수도 있습니다.","위원장의 추천을 받아 여성가족부장관의 제청으로 대통령이 임명하거나 위촉한다":"위원은 위원장의 추천을 거쳐 장관이 제청하면 대통령이 임명하거나 위촉하는 절차를 따릅니다.","의무교육과정에 있는 가해학생에 대하여는 적용하지 않는다":"퇴학처분은 초등학교와 중학교처럼 의무교육 과정의 학생에게는 내릴 수 없습니다.","일탈행동도 청소년 비행에 해당된다":"법을 어기지 않았더라도 사회 규범에서 벗어난 행동이면 청소년 비행으로 봅니다.","임상척도의 의미를 정확하게 평가한다":"척도 점수만으로 알기 어려운 의미를 위기 문항 확인으로 보완해 정확히 해석합니다.","자신의 행동으로 인한 부정적인 결과에 대해 일반적인 염려가 결여되어 있다":"자기 행동이 학업이나 처벌에 줄 불이익을 걱정하는 보통의 반응이 부족합니다.","자주 다른 사람을 괴롭히고, 위협하거나 협박한다":"품행장애의 사람에 대한 공격 행동으로, 타인을 반복해서 겁주고 괴롭히는 것입니다.","재산 피해나 파괴, 그리고/또는 동물이나 다른 사람에게 상해를 입힐 수 있는 신체적 폭행을 포함":"폭발 행동에는 물건을 부수는 것과 사람이나 동물을 다치게 하는 폭행이 들어갑니다.","재적위원의 과반수의 출석으로 개의하고, 출석위원 과반수의 찬성으로 의결 한다":"전체 위원의 절반을 넘게 모여야 회의가 열리고 참석자의 과반이 찬성해야 결정됩니다.","재통합적 수치심(Reintegrative Shaming)이론이":"회복적 사법의 이론적 배경으로 재통합적 수치심 이론이 있다는 문장의 앞부분입니다.","적응적 행동에 대한 보상 및 강화를 제공한다":"바람직한 행동을 하면 보상을 주어 그 행동이 더 자주 나오도록 합니다.","정기적인 학급토의를 진행한다":"학급에서 주기적으로 폭력에 대해 토론하게 하여 학생들의 인식을 바꿉니다.","조사 또는 심리를 할 때에 정신건강의학과의사ㆍ심리학자ㆍ사회사업가ㆍ교육자나 그 밖의 전문가의 진단, 소년분류심사원의 분류심사 결과와 의견, 보호관찰소의 조사결과와 의견 등을 고려하여야 한다":"판사는 여러 전문가의 진단과 심사원 및 보호관찰소의 조사 결과를 참고해 심리하여야 합니다.","조치 요청이 있을 시, 교육장은 14일 이내에 해당 조치를 하여야 한다":"조치를 요청받은 교육장에게는 14일이라는 처리 기한이 있습니다.","지방자치단체는 CYS-Net을 구축·운영하여야 한다":"지방자치단체가 지역 청소년 안전망인 CYS-Net을 반드시 만들어 운영해야 합니다.","지방자치단체의 장은 통합지원체계의 원활한 운영을 위하여 필요하다고 인정하는 경우에는 위기청소년의 복지 및 보호와 관련된 정책 등 대통령령으로 정하는 사항을 심의하는 청소년 복지심의위원회를 둘 수 있다":"지방자치단체장은 필요하면 위기 청소년 정책을 심의하는 복지심의위원회를 설치할 수 있습니다.","처벌보다 보호 및 교육의 관점을 중요시 한다":"청소년 비행에는 벌을 주기보다 보호하고 가르쳐 바른 방향으로 이끄는 접근을 앞세웁니다.","청소년비행은 시간적ㆍ공간적 상대성을 고려한다":"어떤 행동이 비행인지는 시대와 사회에 따라 달라지므로 시기와 장소를 함께 따져야 합니다.","청소년유해매체물, 청소년유해약물등, 청소년유해업소 등에 관한 사항을 심의ㆍ결정한다":"청소년에게 해로운 매체와 약물과 업소가 무엇인지 정하는 것이 위원회의 역할입니다.","청소년이라는 지위 때문에 비행으로 간주되어 지위비행이라고 한다":"음주나 흡연처럼 어른에게는 허용되는 행동이 청소년에게는 신분 탓에 비행이 되는 경우입니다.","치료계획을 수립하기 위해 초기에 진단이나 평가를 한다":"문제 행동의 빈도와 상황을 파악해야 개입 방법을 정할 수 있어 처음에 평가합니다.","통합지원체계를 구성하는 기관ㆍ단체의 장 또는 종사자와 그 밖에 청소년복지에 대하여 지식과 경험이 풍부한 사람으로 구성한다":"위원은 통합지원체계에 속한 기관의 사람과 청소년복지에 밝은 전문가들로 이루어집니다.","통합지원체계의 구축ㆍ운영을 지원하여야 한다":"국가는 위기 청소년을 연결하는 통합지원체계가 갖추어지고 운영되도록 도와야 합니다.","폭력예방에 학부모의 참여를 유도한다":"학교만으로는 한계가 있어 가정에서도 예방에 함께하도록 학부모를 참여시킵니다.","피상적이거나 가식적인 정서를 제외하고는 자신의 기분이나 정서를 다른 사람에게 드러내지 않는다":"보여 주는 감정이 있어도 겉치레일 뿐 진짜 속마음은 거의 표현하지 않습니다.","피해자와 대면하지 않은 상황에서 귀중품을 절도한다":"강도처럼 마주 보고 빼앗는 것이 아니라 상대가 없는 곳에서 몰래 훔치는 행동입니다.","학교나 직업세계에서 비행이 아닌 다른 방법으로 자신의 목표를 정립하고 성취할 수 있도록 돕는다":"비행이 아닌 학업이나 직업 같은 길로 목표를 세우고 이루는 경험을 하게 합니다.","학교에서 보다 나은 또래관계를 만들기 위한 목적을 가지고 있다":"예방프로그램은 학생들 사이의 관계를 건강하게 만들어 폭력이 줄도록 하는 것이 목적입니다.","학교폭력대책심의위원회는 조치를 요청하기 전에 가해학생 및 보호자에게 의견진술의 기회를 부여해야 한다":"위원회가 조치를 요청하기 전에 가해 학생과 보호자의 말을 먼저 들어야 합니다.","학업복귀와 사회진입을 위한 지원 사업이 활성화되었다":"학교를 그만둔 청소년이 학업에 돌아가거나 사회로 나아가도록 돕는 사업이 늘었습니다.","행동계약이나 숙제를 활용한다":"행동 목표와 보상을 문서로 약속하거나 과제를 주어 일상에서 실천하게 합니다.","행동 손상 정도나 주관적 불편감 수준을 보다 정확히 측정 한다":"행동이 얼마나 지장을 주는지와 본인이 느끼는 괴로움의 크기를 더 정밀하게 잴 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
